import{_ as o,r as n,o as l,c,e as s,a as i,s as u}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Submission - October CMS - 4.x","titleTemplate":false,"description":"Displays a form for accepting user submitted content.","frontmatter":{"subtitle":"Displays a form for accepting user submitted content."},"headers":[{"level":2,"title":"Available Properties","slug":"available-properties","link":"#available-properties","children":[]},{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"Rendering Custom Markup","slug":"rendering-custom-markup","link":"#rendering-custom-markup","children":[{"level":3,"title":"Building Fields from the Schema","slug":"building-fields-from-the-schema","link":"#building-fields-from-the-schema","children":[]}]},{"level":2,"title":"Multi-Step Forms","slug":"multi-step-forms","link":"#multi-step-forms","children":[{"level":3,"title":"Tagging Step Fields","slug":"tagging-step-fields","link":"#tagging-step-fields","children":[]},{"level":3,"title":"Navigating Steps","slug":"navigating-steps","link":"#navigating-steps","children":[]},{"level":3,"title":"Partial Submissions","slug":"partial-submissions","link":"#partial-submissions","children":[]}]},{"level":2,"title":"File Uploads","slug":"file-uploads","link":"#file-uploads","children":[]},{"level":2,"title":"Spam Protection","slug":"spam-protection","link":"#spam-protection","children":[]},{"level":2,"title":"Email Notifications","slug":"email-notifications","link":"#email-notifications","children":[]},{"level":2,"title":"Events","slug":"events","link":"#events","children":[{"level":3,"title":"Sending a Visitor Confirmation","slug":"sending-a-visitor-confirmation","link":"#sending-a-visitor-confirmation","children":[]},{"level":3,"title":"Multi-Step Events","slug":"multi-step-events","link":"#multi-step-events","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/cms/components/submission.md","filePath":"4.x/cms/components/submission.md"}'),r={name:"4.x/cms/components/submission.md"};function k(d,a,m,g,h,f){const t=n("pre-heading"),e=n("post-heading"),p=n("VideoBlockLink");return l(),c("div",null,[s(t),a[0]||(a[0]=i("h1",null,"Submission",-1)),s(e),s(p,{src:"https://www.youtube.com/watch?v=SzIYzEXF3Wk",title:"User Content Submissions",description:"This video demonstrates how to accept user submitted content, such as comments and contact forms, with the submission component.",prompt:"Watch the demonstration"}),a[1]||(a[1]=u(`<p>The <code>submission</code> component displays a frontend form for a <a href="./../tailor/blueprints.html#submission">submission blueprint</a>, used to capture user generated content such as blog comments and contact form submissions. The component handles rendering the form, validating the input and saving the record for moderation.</p><h2 id="available-properties"><a href="#available-properties" class="header-anchor">#</a> Available Properties</h2><p>The following properties are supported by the component.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>The handle of the <a href="./../tailor/blueprints.html#submission">submission blueprint</a>.</td></tr><tr><td><strong>wizard</strong></td><td>enables <a href="#multi-step-forms">multi-step forms</a> where the submission is captured across several steps. Default: <code>false</code></td></tr></tbody></table></div><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><p>The following adds a submission form for the <strong>Blog\\Comment</strong> blueprint to the page. Rendering the component displays a complete form generated from the blueprint fields, including spam protection and file upload support.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">submission commentForm</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Comment</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>commentForm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>When the form is submitted successfully, the record is saved with a <strong>Pending</strong> status, ready for moderation in the admin panel. Validation rules defined on the blueprint fields are applied automatically and displayed against the form fields.</p><h2 id="rendering-custom-markup"><a href="#rendering-custom-markup" class="header-anchor">#</a> Rendering Custom Markup</h2><p>For complete control over the form markup, submit the fields directly to the <code>onFormSubmit</code> AJAX handler using field names matching the blueprint. The following renders a custom comment form that links each comment to the current blog post using a hidden field.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> formSubmitted <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-success<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Thank you for your comment! It will appear here once it has been approved.
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>commentForm::onFormSubmit<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-flash</span><span class="token punctuation">&gt;</span></span>

        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hidden<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>post<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>id <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>author_name<span class="token punctuation">&quot;</span></span> <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Name<span class="token punctuation">&quot;</span></span> <span class="token attr-name">required</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>email<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>author_email<span class="token punctuation">&quot;</span></span> <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Email address<span class="token punctuation">&quot;</span></span> <span class="token attr-name">required</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>textarea</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>content<span class="token punctuation">&quot;</span></span> <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Comment<span class="token punctuation">&quot;</span></span> <span class="token attr-name">required</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>textarea</span><span class="token punctuation">&gt;</span></span>

        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none</span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>_oc_hp<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">autocomplete</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>off<span class="token punctuation">&quot;</span></span> <span class="token attr-name">tabindex</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
            Submit
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>After a successful submission, the partial is updated with the <code>formSubmitted</code> variable set to <strong>true</strong> and the <code>formModel</code> variable containing the saved record.</p><div class="custom-block tip"><p>Wrap the form in an <a href="./../ajax/update-partials.html">AJAX partial</a> using the <code>{% ajaxPartial %}</code> tag so it can refresh itself when submitted.</p></div><h3 id="building-fields-from-the-schema"><a href="#building-fields-from-the-schema" class="header-anchor">#</a> Building Fields from the Schema</h3><p>The <code>formGetFields</code> method returns the blueprint fields as an array, letting you build custom markup while keeping the field definitions in the blueprint. Each field includes the <strong>name</strong>, <strong>label</strong>, <strong>htmlType</strong>, <strong>options</strong>, <strong>required</strong>, <strong>placeholder</strong>, <strong>comment</strong> and <strong>multiple</strong> values.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> field <span class="token operator">in</span> commentForm<span class="token punctuation">.</span>formGetFields <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>label</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> field<span class="token punctuation">.</span>label <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>label</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> field<span class="token punctuation">.</span>htmlType <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> field<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> field<span class="token punctuation">.</span>required <span class="token delimiter punctuation">%}</span></span>required<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="multi-step-forms"><a href="#multi-step-forms" class="header-anchor">#</a> Multi-Step Forms</h2><p>Setting the <code>wizard</code> property to <code>true</code> enables multi-step submissions, where the form is broken into several steps that are saved progressively against the same record. Each step is persisted as the visitor advances, so a partially completed form is captured as a lead even when the later steps are abandoned.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">submission surveyForm</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Survey\\Feedback</span>&quot;</span>
<span class="token key attr-name">wizard</span> <span class="token punctuation">=</span> <span class="token value attr-value">1</span>
</code></pre></div><h3 id="tagging-step-fields"><a href="#tagging-step-fields" class="header-anchor">#</a> Tagging Step Fields</h3><p>Fields opt into a step using the <code>tags</code> property on the <a href="./../tailor/blueprints.html#multi-step-fields">blueprint field</a>, which accepts a single tag or an array of tags. A tag defines a group of fields that are validated and saved together as one step. Tagging fields is what makes a blueprint usable as a wizard, since a blueprint without tagged fields has no steps to advance through.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">rating</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Rating
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required
        <span class="token key atrule">tags</span><span class="token punctuation">:</span> step1

    <span class="token key atrule">comments</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Comments
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> required<span class="token punctuation">|</span>max<span class="token punctuation">:</span><span class="token number">2000</span>
        <span class="token key atrule">tags</span><span class="token punctuation">:</span> step2
</code></pre></div><p>When a step is saved, only the validation rules for the fields belonging to that step are applied, so each step can define its own required fields without affecting the others. The full rule set for every field is enforced later when the form is completed.</p><h3 id="navigating-steps"><a href="#navigating-steps" class="header-anchor">#</a> Navigating Steps</h3><p>Two AJAX handlers move between steps, one for each direction.</p><div class="table"><table tabindex="0"><thead><tr><th>Handler</th><th>Posted value</th><th>Description</th></tr></thead><tbody><tr><td><strong>onFormStep</strong></td><td><code>_form_step</code></td><td>the tag of the fields to validate and save. This is the forward (<strong>Next</strong>) action, and the saved step becomes the active step.</td></tr><tr><td><strong>onFormGoto</strong></td><td><code>_form_goto</code></td><td>the step to display without validating or saving. This is the backward (<strong>Back</strong>) action, so the visitor never loses earlier input.</td></tr></tbody></table></div><p>Keeping the two directions on separate handlers means a <strong>Back</strong> action never triggers validation, even when the step form contains a hidden <code>_form_step</code> field that gets submitted with the request.</p><p>The active step is available as the <code>formTag</code> variable, and the record being built is available as the <code>formModel</code> variable, letting you display the appropriate step and pre-fill fields with previously saved values.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>survey-form<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> formSubmitted <span class="token delimiter punctuation">%}</span></span>
        Thank you for your feedback!

    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> formTag <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>step1<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>surveyForm::onFormSubmit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>textarea</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>comments<span class="token punctuation">&quot;</span></span> <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Comments<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> formModel<span class="token punctuation">.</span>comments <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>textarea</span><span class="token punctuation">&gt;</span></span>

            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>surveyForm::onFormGoto<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _form_goto: &#39;&#39; }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Back
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
                Send Feedback
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>surveyForm::onFormStep<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hidden<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>_form_step<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>step1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>select</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>rating<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>option</span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>good<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Good<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>option</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>option</span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bad<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Bad<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>option</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>select</span><span class="token punctuation">&gt;</span></span>

            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
                Continue
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Here the first screen saves the <code>step1</code> fields, which becomes the active step and displays the screen collecting the remaining input. The final step submits to the <code>onFormSubmit</code> handler as usual, which completes the record and enforces the full validation rule set across all fields. The <strong>Back</strong> button posts an empty <code>_form_goto</code>, which matches no named step and falls through to the initial screen rendered by the template&#39;s <code>{% else %}</code> branch.</p><h3 id="partial-submissions"><a href="#partial-submissions" class="header-anchor">#</a> Partial Submissions</h3><p>While a wizard is in progress, the record is flagged as a partial submission and tracked in the visitor session. Partial records appear in the admin panel with a <strong>Partial</strong> status, distinguishing an abandoned form from a completed one awaiting moderation. Completing the form clears the partial flag, and the record moves to the normal <strong>Pending</strong> status.</p><p>Partial submissions are never purged automatically, since they represent captured leads. To remove them, reject the record in the admin panel, after which it follows the standard <a href="./../tailor/blueprints.html#submission">rejected submission retention</a>.</p><h2 id="file-uploads"><a href="#file-uploads" class="header-anchor">#</a> File Uploads</h2><p>Blueprints using the <a href="./../../element/form/widget-fileupload.html">file upload field</a> accept uploaded files with the submission. Include the <code>data-request-files</code> attribute on the form tag to enable file uploads, and the <code>formHasFileFields</code> method can check if any file fields are defined.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>commentForm::onFormSubmit<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> commentForm<span class="token punctuation">.</span>formHasFileFields <span class="token delimiter punctuation">%}</span></span>data-request-files<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span></span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>photo<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Uploaded files are validated against the maximum upload size and the allowed extensions from the field <code>fileTypes</code> configuration. Fields allowing multiple files use array naming, for example, <code>name=&quot;photos[]&quot;</code>, and the file count is validated against the field <code>maxFiles</code> configuration.</p><h2 id="spam-protection"><a href="#spam-protection" class="header-anchor">#</a> Spam Protection</h2><p>The component includes several layers of spam protection for the public form endpoint.</p><ul><li><strong>Honeypot</strong>: submissions containing a value for the hidden <code>_oc_hp</code> field are blocked. Include this field in custom markup as shown above.</li><li><strong>Rate limiting</strong>: submissions are limited to 6 per minute for each IP address.</li><li><strong>Moderation</strong>: records are hidden from the frontend until approved in the admin panel.</li></ul><p>The rate limit can be changed by overriding the <code>formGetThrottleRate</code> method on the component class, returning the maximum submissions per minute, or <code>0</code> to disable the limit. For <a href="#multi-step-forms">multi-step forms</a>, only the creation of a new record is rate limited, so navigating between the steps of an in-progress submission is never throttled.</p><h2 id="email-notifications"><a href="#email-notifications" class="header-anchor">#</a> Email Notifications</h2><p>Submissions can notify an admin user group by email as they arrive, configured with the <code>notifyGroup</code> property on the <a href="./../tailor/blueprints.html#email-notifications">submission blueprint</a>. The notification is sent after the record is saved and includes a link to moderate the record in the admin panel.</p><h2 id="events"><a href="#events" class="header-anchor">#</a> Events</h2><p>The <code>cms.form.beforeSubmit</code> event fires before the submission is saved, and throwing an exception from a listener rejects it. This is the extension point for connecting spam scoring services, CAPTCHA verification or blocklists.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.form.beforeSubmit&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$component</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">SpamService</span><span class="token operator">::</span><span class="token function">isSpam</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;content&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Submission rejected.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>cms.form.submit</code> event fires after the submission has been saved, useful for custom notification logic beyond the built-in <a href="./../tailor/blueprints.html#email-notifications">admin group notifications</a>.</p><h3 id="sending-a-visitor-confirmation"><a href="#sending-a-visitor-confirmation" class="header-anchor">#</a> Sending a Visitor Confirmation</h3><p>Use the <code>cms.form.submit</code> event to send a confirmation email to the person submitting the form. The following sends a receipt using the submitted <code>email</code> field, checking the component alias so the listener only applies to the intended form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.form.submit&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$component</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$component</span><span class="token operator">-&gt;</span><span class="token property">alias</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;contactForm&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$email</span> <span class="token operator">=</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">email</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">filter_var</span><span class="token punctuation">(</span><span class="token variable">$email</span><span class="token punctuation">,</span> <span class="token constant">FILTER_VALIDATE_EMAIL</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$email</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;contact:submission-received&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">title</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Auto-responders send mail to an address supplied by the visitor, making them a target for abuse, including inbox flooding of third parties and damage to your mail sender reputation from bounced or fake addresses. Avoid echoing the submitted content back in the message, and consider pairing this with CAPTCHA verification using the <code>cms.form.beforeSubmit</code> event.</p></div><h3 id="multi-step-events"><a href="#multi-step-events" class="header-anchor">#</a> Multi-Step Events</h3><p>For <a href="#multi-step-forms">multi-step forms</a>, the <code>cms.form.beforeStep</code> and <code>cms.form.step</code> events fire as each step is saved, before and after respectively. Both receive the component, the record and the tag of the step being saved. Throwing an exception from a <code>cms.form.beforeStep</code> listener rejects the step, which is useful for verifying a CAPTCHA on the first step only.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.form.beforeStep&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$component</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">,</span> <span class="token variable">$tag</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$tag</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;step1&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span><span class="token class-name static-context">CaptchaService</span><span class="token operator">::</span><span class="token function">verify</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;captcha&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Please complete the captcha.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../tailor/blueprints.html#submission">Submission Blueprint</a></li><li><a href="./../ajax/update-partials.html">AJAX Update Partials</a></li><li><a href="./../features/flash-messages.html">Flash Messages</a></li></ul></div>`,56))])}const q=o(r,[["render",k]]);export{b as __pageData,q as default};
